export type KpiUnit = 'currency' | 'percent' | 'number'

export type Kpi = {
  id: string
  label: string
  value: number
  unit: KpiUnit
  change: number
  trend: number[]
}

export function formatKpiValue(value: number, unit: KpiUnit): string {
  if (unit === 'currency') {
    return value.toLocaleString('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    })
  }
  if (unit === 'percent') {
    return `${value.toFixed(1)}%`
  }
  return value.toLocaleString('en-US')
}

interface SparklineProps {
  data: number[]
  width?: number
  height?: number
  className?: string
}

export function Sparkline({
  data,
  width = 96,
  height = 28,
  className,
}: SparklineProps) {
  if (data.length < 2) return null

  const min = Math.min(...data)
  const max = Math.max(...data)
  const range = max - min || 1
  const stepX = width / (data.length - 1)

  const points = data
    .map((value, i) => {
      const x = i * stepX
      const y = height - ((value - min) / range) * height
      return `${x.toFixed(1)},${y.toFixed(1)}`
    })
    .join(' ')

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      className={className}
      aria-hidden="true"
    >
      <polyline
        points={points}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

'use client'

import type { ColumnDef } from '@tanstack/react-table'
import { Minus, TrendingDown, TrendingUp } from 'lucide-react'

import { cn } from '#/lib/utils.ts'
import type { Kpi } from './kpi'
import { formatKpiValue } from './kpi'
import { Sparkline } from './sparkline'

export const columns: ColumnDef<Kpi>[] = [
  {
    accessorKey: 'label',
    header: 'Metric',
    cell: ({ getValue }) => (
      <span className="font-medium">{getValue() as string}</span>
    ),
  },
  {
    accessorKey: 'value',
    header: 'Value',
    cell: ({ row }) => formatKpiValue(row.original.value, row.original.unit),
  },
  {
    accessorKey: 'change',
    header: 'Change',
    cell: ({ getValue }) => {
      const change = getValue() as number
      const isFlat = change === 0
      const isUp = change > 0
      const Icon = isFlat ? Minus : isUp ? TrendingUp : TrendingDown

      return (
        <span
          className={cn(
            'inline-flex items-center gap-1 text-sm font-medium',
            isFlat
              ? 'text-muted-foreground'
              : isUp
                ? 'text-emerald-600 dark:text-emerald-500'
                : 'text-rose-600 dark:text-rose-500',
          )}
        >
          <Icon className="h-3.5 w-3.5" />
          {isUp ? '+' : ''}
          {change.toFixed(1)}%
        </span>
      )
    },
  },
  {
    id: 'trend',
    header: 'Trend',
    cell: ({ row }) => (
      <Sparkline
        data={row.original.trend}
        className={cn(
          'h-7 w-24',
          row.original.change >= 0
            ? 'text-emerald-600 dark:text-emerald-500'
            : 'text-rose-600 dark:text-rose-500',
        )}
      />
    ),
  },
]

'use client'

import {
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ColumnDef } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import type { Kpi } from './kpi'

interface KpiTableProps {
  columns: ColumnDef<Kpi, any>[]
  data: Kpi[]
}

export function KpiTable({ columns, data }: KpiTableProps) {
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
  })

  return (
    <div className="overflow-hidden rounded-md border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id} className="h-8 text-xs">
                  {header.isPlaceholder
                    ? null
                    : flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.map((row) => (
            <TableRow key={row.id}>
              {row.getVisibleCells().map((cell) => (
                <TableCell key={cell.id} className="py-2">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}
